static const Core::sacnReceiver::rxConfig u1_h{1, sacnPolicy::timeoutPolicy::HOLD};

static void test_bad_bytes()
{
    safeNode n{u1_h};
    uint8_t garb[638] = {};
    uint8_t pak[sizeof(uni1_ch1_8_255_bytes)];
    memcpy(pak, uni1_ch1_8_255_bytes, sizeof(pak));
    pak[constants::offsets::rootVector]++;

    assert(!n.onPacket(garb, sizeof(garb), 0));
    assert(!n.onPacket(pak, sizeof(pak), 0));
    assert(!n.onPacket(uni1_ch1_8_255_bytes, 100, 0));

    DMXFrame out;
    assert(!n.latestFrame(&out, 0));
    std::cout << "test_bad_bytes good\n";
}

// bytes in, frame out
static void test_bytes_to_frame()
{
    safeNode n{u1_h};
    assert(n.onPacket(uni1_ch1_8_255_bytes, sizeof(uni1_ch1_8_255_bytes), 0));

    DMXFrame out;
    assert(n.latestFrame(&out, 0));
    for (int i = 0; i < 8; i++)
        assert(out.data[i] == 255);
    for (int i = 8; i < 512; i++)
        assert(out.data[i] == 0);
    std::cout << "test_bytes_to_frame good\n";
}

// todo: stress test threading with seperate reader and writer

int main()
{
    test_bad_bytes();
    test_bytes_to_frame();

    std::cout << "All tests passed" << std::endl;
    return 0;
}
